$listing=null;$enquiry=null;$offer=null;$versions=[];$messages=[];
try{
 if($view==='new-enquiry'){$listing=marketplace_deal_listing($listingId);if($listing['organization_id']===$user['owner_id'])throw new DomainException('Use My Listings to manage your own equipment.',409);$pageTitle='Make an enquiry';}
 elseif($view==='new-offer'){$listing=marketplace_deal_listing($listingId);if($listing['organization_id']===$user['owner_id'])throw new DomainException('You cannot make an offer on your own listing.',409);$linkedEnquiry=marketplace_text($_GET,'enquiry',36);if($linkedEnquiry){$context=marketplace_enquiry($user,$linkedEnquiry);if($context['listing_id']!==$listingId||$context['buyer_organization_id']!==$user['owner_id'])throw new DomainException('The enquiry does not match this listing.',422);$listing['enquiry_id']=$linkedEnquiry;}$pageTitle='Make an offer';}
 elseif($view==='enquiry'){$enquiry=marketplace_enquiry($user,$id);$listing=marketplace_context_listing($enquiry['listing_id']);$messages=rows('SELECT m.*,u.full_name,a.id attachment_id,a.file_name,a.mime_type,a.file_size,f.status offer_status,f.current_version FROM marketplace_messages m JOIN users u ON u.id=m.sender_user_id LEFT JOIN marketplace_message_attachments a ON a.message_id=m.id LEFT JOIN marketplace_offers f ON f.id=m.referenced_offer_id WHERE m.conversation_id=? ORDER BY m.created_at,m.id',[$enquiry['conversation_id']]);$pageTitle=$enquiry['subject'];}
 elseif($view==='offer'){$offer=marketplace_offer($user,$id);marketplace_mark_offer_viewed($user,$offer);$offer=marketplace_offer($user,$id);$versions=rows('SELECT v.*,u.full_name,o.name organization_name FROM marketplace_offer_versions v JOIN users u ON u.id=v.proposed_by_user_id JOIN owners o ON o.id=v.proposed_by_organization_id WHERE v.offer_id=? ORDER BY v.version_number DESC',[$id]);$pageTitle='Offer '.$offer['status'];}
 else throw new DomainException('Marketplace workspace not found.',404);
}catch(Throwable $error){http_response_code($error instanceof DomainException?$error->getCode():500);$problem=$error instanceof DomainException?$error->getMessage():'The marketplace workspace could not be loaded.';$pageTitle='Marketplace workspace';}
