function deal_money($value,string $currency):string{return $currency.' '.number_format((float)$value,2);}
function deal_terms_form(array $source,string $type,string $action,string $offerId=''):void{$valid=isset($source['valid_until'])?gmdate('Y-m-d\TH:i',strtotime($source['valid_until'])):gmdate('Y-m-d\TH:i',time()+604800);?>
<form action="marketplace-negotiation-action" method="post" class="deal-form"><?= csrf_field() ?><input type="hidden" name="action" value="<?= e($action) ?>"><?php if($offerId):?><input type="hidden" name="offer_id" value="<?= e($offerId) ?>"><?php else:?><input type="hidden" name="listing_id" value="<?= e($source['id']) ?>"><input type="hidden" name="transaction_type" value="<?= e($type) ?>"><?php if(!empty($source['enquiry_id'])):?><input type="hidden" name="enquiry_id" value="<?= e($source['enquiry_id']) ?>"><?php endif;?><?php endif;?>
<div class="form-grid"><label>Offer amount<input type="number" min="0.01" step="0.01" name="amount" required value="<?= e((string)($source['amount']??($type==='SALE'?($source['asking_price']??''):($source['lease_rate']??'')))) ?>"></label><label>Currency<input name="currency" maxlength="3" required value="<?= e($source['currency']??($type==='SALE'?($source['sale_currency']??'NGN'):($source['lease_currency']??'NGN'))) ?>"></label>
<?php if($type==='LEASE'):?><label>Rate basis<select name="pricing_basis"><?php foreach(['HOURLY','DAILY','WEEKLY','MONTHLY','PROJECT'] as $option):?><option <?= ($source['pricing_basis']??strtoupper((string)($source['duration_unit']??'DAILY')))===$option?'selected':'' ?>><?= $option ?></option><?php endforeach;?></select></label><label>Operator requirement<select name="operator_requirement"><?php foreach(['OWNER_OPERATOR'=>'Owner supplies operator','LESSEE_OPERATOR'=>'Lessee supplies operator','TO_BE_DETERMINED'=>'To be determined'] as $value=>$label):?><option value="<?= $value ?>" <?= ($source['operator_requirement']??'TO_BE_DETERMINED')===$value?'selected':'' ?>><?= e($label) ?></option><?php endforeach;?></select></label><label>Start date<input type="date" name="lease_start_date" required value="<?= e($source['lease_start_date']??gmdate('Y-m-d',time()+86400)) ?>"></label><label>End date<input type="date" name="lease_end_date" required value="<?= e($source['lease_end_date']??gmdate('Y-m-d',time()+2678400)) ?>"></label><?php endif;?>
<label>Project country<input name="project_country" maxlength="100" value="<?= e($source['project_country']??'Nigeria') ?>"></label><label>Project state / region<input name="project_state" maxlength="100" value="<?= e($source['project_state']??'') ?>"></label><label>Project city<input name="project_city" maxlength="100" value="<?= e($source['project_city']??'') ?>"></label><label>Offer valid until<input type="datetime-local" name="valid_until" required value="<?= e($valid) ?>"></label>
<?php if($type==='LEASE'):?><label>Mobilization cost<input type="number" min="0" step="0.01" name="mobilization_cost" value="<?= e((string)($source['mobilization_cost']??'')) ?>"></label><label>Security deposit<input type="number" min="0" step="0.01" name="security_deposit" value="<?= e((string)($source['security_deposit']??'')) ?>"></label><?php endif;?><label class="full">Intended use<textarea name="intended_use" rows="3"><?= e($source['intended_use']??'') ?></textarea></label><label class="full">Commercial conditions<textarea name="commercial_conditions" rows="3"><?= e($source['commercial_conditions']??'') ?></textarea></label><label class="full">Additional requirements<textarea name="additional_requirements" rows="3"><?= e($source['additional_requirements']??'') ?></textarea></label></div>
<div class="form-actions"><button class="market-button"><?= $action==='offer.counter'?'Submit counter offer':'Submit binding offer' ?></button><?php if($action==='offer.submit'):?><button class="secondary-button" name="action" value="offer.draft">Save draft</button><?php endif;?></div></form><?php }
