<?php elseif($view==='new-offer'):?><header class="manage-head"><div><p class="market-kicker">COMMERCIAL OFFER</p><h1><?= e($listing['title']) ?></h1><p>Submit terms to <?= e($listing['owner_name']) ?>. Each later counter is stored as a new version.</p></div></header><section class="deal-panel"><div class="deal-type-picker"><?php if($listing['purpose']!=='SALE'):?><a href="marketplace-deal?view=new-offer&listing=<?= e($listing['id']) ?>&type=LEASE" <?= ($_GET['type']??'LEASE')==='LEASE'?'aria-current="page"':'' ?>>Lease offer</a><?php endif;?><?php if($listing['purpose']!=='LEASE'):?><a href="marketplace-deal?view=new-offer&listing=<?= e($listing['id']) ?>&type=SALE" <?= ($_GET['type']??'')==='SALE'?'aria-current="page"':'' ?>>Purchase offer</a><?php endif;?></div><?php $type=($_GET['type']??($listing['purpose']==='SALE'?'SALE':'LEASE'));if(!in_array($type,['LEASE','SALE'],true))$type='LEASE';foreach(['lease_start_date','lease_end_date'] as $dateField){$date=(string)($_GET[$dateField]??'');if(preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))$listing[$dateField]=$date;}deal_terms_form($listing,$type,'offer.submit');?></section>
<?php elseif($view==='enquiry'):?><header class="manage-head"><div><p class="market-kicker"><?= e(str_replace('_',' ',$enquiry['category'])) ?> · <?= e($enquiry['status']) ?></p><h1><?= e($enquiry['subject']) ?></h1><p><a href="marketplace-listing?id=<?= e($enquiry['listing_id']) ?>"><?= e($enquiry['listing_title']) ?></a> · <?= e($enquiry['buyer_name']) ?> and <?= e($enquiry['owner_name']) ?></p></div><?php if($enquiry['status']!=='CLOSED'&&$user['owner_id']===$enquiry['buyer_organization_id']):?><a class="market-button" href="marketplace-deal?view=new-offer&listing=<?= e($enquiry['listing_id']) ?>&enquiry=<?= e($enquiry['id']) ?>">Make offer</a><?php endif;?></header><section class="conversation"><div class="message-list"><?php foreach($messages as $message):?><article class="message <?= $message['sender_organization_id']===$user['owner_id']?'mine':'' ?>"><header><strong><?= e($message['full_name']) ?></strong><time><?= e($message['created_at']) ?></time></header><?php if($message['message_text']):?><p><?= nl2br(e($message['message_text'])) ?></p><?php endif;?><?php if($message['attachment_id']):?><a class="attachment" href="marketplace-attachment?id=<?= e($message['attachment_id']) ?>">📎 <?= e($message['file_name']) ?> (<?= number_format($message['file_size']/1024,1) ?> KB)</a><?php endif;?><?php if($message['referenced_offer_id']):?><a class="offer-reference" href="marketplace-deal?view=offer&id=<?= e($message['referenced_offer_id']) ?>">Offer <?= e($message['offer_status']) ?> · version <?= (int)$message['current_version'] ?></a><?php endif;?></article><?php endforeach;?></div><?php if($enquiry['status']!=='CLOSED'):?><form class="message-compose" action="marketplace-negotiation-action" method="post" enctype="multipart/form-data"><?= csrf_field() ?><input type="hidden" name="action" value="message.send"><input type="hidden" name="enquiry_id" value="<?= e($enquiry['id']) ?>"><label>Reply<textarea name="message" maxlength="5000" rows="4"></textarea></label><label>Attach image or document<input type="file" name="attachment" accept=".jpg,.jpeg,.png,.webp,.pdf,.doc,.docx"></label><button class="market-button">Send message</button></form><form action="marketplace-negotiation-action" method="post" class="inline-form"><?= csrf_field() ?><input type="hidden" name="action" value="enquiry.close"><input type="hidden" name="enquiry_id" value="<?= e($enquiry['id']) ?>"><button>Close enquiry</button></form><?php endif;?></section>
<?php elseif($view==='offer'):?><?php $final=in_array($offer['status'],['ACCEPTED','REJECTED','WITHDRAWN','EXPIRED'],true);$canRespond=!$final&&$offer['proposed_by_organization_id']!==$user['owner_id']&&marketplace_negotiation_manager($user);?><header class="manage-head"><div><p class="market-kicker"><?= e($offer['transaction_type']) ?> OFFER · <?= e($offer['status']) ?></p><h1><?= e($offer['listing_title']) ?></h1><p><?= e($offer['buyer_name']) ?> → <?= e($offer['seller_name']) ?> · current version <?= (int)$offer['current_version'] ?></p></div><a href="marketplace-listing?id=<?= e($offer['listing_id']) ?>">View equipment</a></header><div class="offer-layout"><section class="deal-panel"><h2>Current commercial terms</h2><dl class="offer-terms"><dt>Amount</dt><dd><?= e(deal_money($offer['amount'],$offer['currency']).' / '.strtolower($offer['pricing_basis'])) ?></dd><?php if($offer['transaction_type']==='LEASE'):?><dt>Dates</dt><dd><?= e($offer['lease_start_date'].' to '.$offer['lease_end_date']) ?></dd><dt>Operator</dt><dd><?= e(str_replace('_',' ',ucwords(strtolower($offer['operator_requirement'])))) ?></dd><?php endif;?><dt>Project location</dt><dd><?= e(implode(', ',array_filter([$offer['project_city'],$offer['project_state'],$offer['project_country']]))) ?></dd><dt>Intended use</dt><dd><?= nl2br(e($offer['intended_use']?:'Not specified')) ?></dd><dt>Conditions</dt><dd><?= nl2br(e($offer['commercial_conditions']?:'No additional conditions')) ?></dd><dt>Valid until</dt><dd><?= e($offer['valid_until']) ?> UTC</dd></dl><?php if($offer['status']==='ACCEPTED'):?><div class="binding-notice"><strong>Accepted terms frozen</strong><p>Version <?= (int)$offer['current_version'] ?> is the binding commercial record for this transaction.</p></div><?php endif;?>
<?php if($canRespond):?><div class="decision-actions"><form action="marketplace-negotiation-action" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="offer.accept"><input type="hidden" name="offer_id" value="<?= e($offer['id']) ?>"><input type="hidden" name="confirmed_version" value="<?= (int)$offer['current_version'] ?>"><label class="confirm"><input type="checkbox" name="confirm_terms" value="1" required> I reviewed and accept version <?= (int)$offer['current_version'] ?> exactly as shown.</label><button class="market-button">Accept offer</button></form><form action="marketplace-negotiation-action" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="offer.reject"><input type="hidden" name="offer_id" value="<?= e($offer['id']) ?>"><button class="danger-button">Reject</button></form></div><details class="counter-panel"><summary>Make a counter offer</summary><?php deal_terms_form($offer,$offer['transaction_type'],'offer.counter',$offer['id']);?></details><?php elseif($offer['status']==='DRAFT'&&$offer['buyer_organization_id']===$user['owner_id']):?><form action="marketplace-negotiation-action" method="post" class="form-actions"><?= csrf_field() ?><input type="hidden" name="action" value="offer.submit-draft"><input type="hidden" name="offer_id" value="<?= e($offer['id']) ?>"><button class="market-button">Submit draft offer</button><button class="danger-button" name="action" value="offer.withdraw">Delete draft</button></form><?php elseif(!$final&&$offer['buyer_organization_id']===$user['owner_id']):?><form action="marketplace-negotiation-action" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="offer.withdraw"><input type="hidden" name="offer_id" value="<?= e($offer['id']) ?>"><button class="danger-button">Withdraw offer</button></form><?php endif;?></section><aside class="version-history"><h2>Version history</h2><?php foreach($versions as $version):?><article><strong>Version <?= (int)$version['version_number'] ?></strong><span><?= e($version['organization_name']) ?></span><b><?= e(deal_money($version['amount'],$version['currency'])) ?></b><small><?= e($version['created_at']) ?> · valid to <?= e($version['valid_until']) ?></small></article><?php endforeach;?></aside></div><?php endif;?>
